files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --text-dim: #a0a0b0;
  --border: #0f3460;
  --focus: #f9c74f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, #1e1e3a 25%, transparent 25%),
    linear-gradient(-45deg, #1e1e3a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1e1e3a 75%),
    linear-gradient(-45deg, transparent 75%, #1e1e3a 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 400px;
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: 0;
  padding: 24px;
  box-shadow: 6px 6px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.field {
  margin-bottom: 20px;
  border: none;
}

label, legend {
  display: block;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-dim);
  margin-bottom: 8px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 1.25rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
}

input[type="number"]:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(249, 199, 79, 0.3);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.tip-btn {
  padding: 12px 4px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 700;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s, transform 0.05s;
}

.tip-btn:hover {
  background: var(--border);
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.tip-btn.active:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 3px dashed var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 0;
}

.result-label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-dim);
}

.result-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .result-value {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipPerPersonEl = document.getElementById('tip-per-person');
  var totalPerPersonEl = document.getElementById('total-per-person');

  var selectedTip = 15;

  function formatMoney(value) {
    if (!isFinite(value) || value < 0) {
      return '$0.00';
    }
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (isNaN(bill) || bill < 0) {
      bill = 0;
    }
    if (isNaN(people) || people < 1) {
      people = 1;
    }

    var tipTotal = bill * (selectedTip / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipPerPersonEl.textContent = formatMoney(tipPerPerson);
    totalPerPersonEl.textContent = formatMoney(totalPerPerson);
  }

  function selectTip(percent, button) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      var isActive = btn === button;
      btn.classList.toggle('active', isActive);
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var percent = parseInt(btn.getAttribute('data-tip'), 10);
      selectTip(percent, btn);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Set initial active button (15%)
  var defaultBtn = tipButtons.filter(function (btn) {
    return btn.getAttribute('data-tip') === '15';
  })[0];
  if (defaultBtn) {
    selectTip(15, defaultBtn);
  }
})();
